func loadDashboard(userId: UUID) async throws -> Dashboard {
    async let profile = loadProfile(id: userId)
    async let feed    = loadFeed(userId: userId)
    async let stats   = loadStats(userId: userId)

    return try await Dashboard(
        profile: profile,
        feed:    feed,
        stats:   stats
    )
}

func loadAll(ids: [UUID]) async throws -> [Profile] {
    try await withThrowingTaskGroup(of: Profile.self) { group in
        for id in ids {
            group.addTask { try await loadProfile(id: id) }
        }
        var result: [Profile] = []
        for try await profile in group {
            result.append(profile)
        }
        return result
    }
}

actor ImageCache {
    private var cache: [URL: UIImage] = [:]
    private let maxSize = 100

    func image(for url: URL) -> UIImage? { cache[url] }

    func store(_ image: UIImage, for url: URL) {
        if cache.count >= maxSize {
            cache.removeValue(forKey: cache.keys.randomElement()!)
        }
        cache[url] = image
    }
}

